export function timelineView(order,solved){
 return `<section class="extended-investigation"><div class="page-heading"><span class="eyebrow">CROSS-REFERENCE / THE MISSING HOURS</span><h1>「毕业」那天，发生了什么？</h1><p>文件都在这里。但它们讲述的，不是同一个版本。</p></div><div class="investigation-layout"><aside class="source-stack"><h2>原始文件</h2><button data-action="evidence:consent"><span>01 / 授权修订</span><strong>一个签名，两个时间。</strong><small>重新阅读原件 →</small></button><button data-action="evidence:ledger"><span>02 / 财务结算</span><strong>一笔写成捐赠的付款。</strong><small>重新阅读原件 →</small></button><button data-action="evidence:route"><span>03 / 夜间转运</span><strong>车与乘员的真实去向。</strong><small>重新阅读原件 →</small></button><p>点击事件卡加入时间线；点击已放入的卡片可以撤回。</p></aside><form class="timeline-workbench" data-form="timeline"><div class="workbench-heading"><span>事件排列</span><small>从早到晚</small></div><ol class="timeline-slots">${[0,1,2,3].map(i=>`<li><span>${String(i+1).padStart(2,'0')}</span>${order[i]?`<button type="button" data-action="timeline-remove:${i}"><strong>${timelineEvents[order[i]].title}</strong><small>撤回 ×</small></button>`:'<div class="timeline-empty">尚未放入事件</div>'}</li>`).join('')}</ol><div class="timeline-options">${Object.entries(timelineEvents).map(([id,event])=>`<button type="button" data-action="timeline-add:${id}" ${order.includes(id)?'disabled':''}><strong>${event.title}</strong><span>${event.detail}</span></button>`).join('')}</div><label for="timeline-conclusion">你发现了什么矛盾？</label><select id="timeline-conclusion" name="conclusion" required><option value="">写下能被记录支持的判断</option value="family">家属在健康检查当天已经接回孩子</option><option value="still-inside">宣布「毕业」时，孩子实际上仍在中心</option><option value="normal">公告与实际离开时间完全相同</option></select><p class="inline-feedback" role="status"></p><button class="btn primary" type="submit">${solved?'再次核对':'提交校对记录'}</button><button type="button" class="btn text" data-action="go:staff">回到档案室</button></form></div></section>`;
}
export function wardView(selected){
 return `<section class="extended-investigation"><div class="page-heading"><span class="eyebrow">NORTH WING / LOCATE 0716</span><h1>小满，就在其中一扇门后。</h1><p>只有病区名称还不够。救援需要一个准确的位置。</p></div><div class="investigation-layout ward-layout"><aside class="source-stack ward-sources"><h2>留在值班台的记录</h2><details open><summary>建筑平面备注</summary><p>北侧房间从西到东依次为 <strong>B2-01、B2-02、B2-03</strong>。南侧为 04、05、06。楼梯在走廊<strong>西端</strong>。</p></details><details><summary>维修工的便签</summary><p><strong>南侧三间</strong>供电检修，昨晚起全部封闭。北侧<strong>最东端</strong>已改成器材库，暂不留人。</p></details><details><summary>夜班交接记录</summary><p>编号 <strong>0716</strong> 仍留观。她<strong>不在紧挨西楼梯的房间</strong>，所在房间的<strong>东侧隔壁</strong>是器材库。外门保持值守。</p></details><p>这些是今晚的记录，不是官网上的「毕业名单」。</p></aside><form class="ward-workbench" data-form="ward"><div class="workbench-heading"><span>北院 · B2 平面图</span><small>上北 / 右东</small></div><div class="floor-plan"><div class="floor-north">北侧</div><div class="room-row">${['01','02','03'].map(n=>roomButton(n,selected)).join('')}</div><div class="ward-corridor"><span>← 西楼梯</span><i></i><span>东端 →</span></div><div class="room-row">${['04','05','06'].map(n=>roomButton(n,selected)).join('')}</div><div class="floor-south">南侧</div></div><div class="room-selection">${selected?`你标记了 <strong>${selected}</strong>`:'在平面图上标记一个房间。'}</div><input type="hidden" name="room" value="${selected||''}"><p class="inline-feedback" role="status"></p><button class="btn primary" type="submit" ${selected?'':'disabled'}>确认小满的位置</button><button type="button" class="btn text" data-action="evidence:truth">重读封存档案</button></form></div></section>`;
}
function roomButton(n,selected){const id=`B2-${n}`;return `<button class="ward-room ${selected===id?'selected':''}" type="button" data-action="ward-select:${id}" aria-pressed="${selected===id}"><span class="room-door"></span><strong>${id}</strong><small>${selected===id?'已标记':'待核对'}</small></button>`;}
